title: Progressive detail
---

import { View, Text } from "react-native";
import { ProgressiveDetail } from "slides:presenting/Composition";

export function Summary() { return <View style={{ padding: 42, borderRadius: 32, backgroundColor: "#123444" }}><Text style={{ color: "white", fontSize: 74 }}>One request</Text><Text style={{ color: "#67e8f9", fontSize: 38 }}>from tap to pixels</Text></View>; }
export function Detail() { return <View style={{ width: 920, gap: 24 }}>{["1  Parse the input", "2  Update state", "3  Draw the view"].map(row => <View key={row} style={{ padding: 22, borderRadius: 20, backgroundColor: "#164e63" }}><Text style={{ color: "white", fontSize: 42 }}>{row}</Text></View>)}</View>; }

# Progressive detail

<View style={{ width: 1696, height: 650 }}>
<Steps count={2}>{step => <ProgressiveDetail expanded={step > 0} summary={<Summary />} detail={<Detail />} style={{ width: 1696, height: 580 }} />}</Steps>
</View>

---
title: Comparison wipe
---

import { View, Text } from "react-native";
import { ComparisonWipe } from "slides:presenting/Composition";

export function Panel({ refined }) { return <View style={{ flex: 1, padding: 90, backgroundColor: refined ? "#083344" : "#172033", justifyContent: "center" }}><Text style={{ color: "white", fontSize: 72 }}>{refined ? "Clear signal" : "Too much noise"}</Text><View style={{ flexDirection: "row", gap: 28, marginTop: 48 }}>{[0, 1, 2, 3].map(i => <View key={i} style={{ width: 245, height: refined ? 95 + i * 65 : 180 + (i % 2) * 150, borderRadius: 18, backgroundColor: refined ? "#22d3ee" : i % 2 ? "#6d28d9" : "#a3346b" }} />)}</View></View>; }

# Comparison wipe

<View style={{ width: 1696, height: 650 }}>
<Steps count={2}>{step => <ComparisonWipe position={step > 0 ? 0.5 : 0} before={<Panel refined={false} />} after={<Panel refined />} beforeLabel="Before" afterLabel="After" style={{ width: 1696, height: 580 }} />}</Steps>
</View>

