title: Content swap
---

import { View, Text } from "react-native";
import { ContentSwap } from "slides:presenting/Composition";

export function Evidence() { return <View style={{ padding: 70, gap: 30 }}><Text style={{ color: "#e0f2fe", fontSize: 70 }}>The evidence</Text><Text style={{ color: "white", fontSize: 110 }}>7 steps → 2 steps</Text><Text style={{ color: "#94a3b8", fontSize: 42 }}>Same outcome, less work</Text></View>; }
export function Takeaway() { return <View style={{ padding: 70, gap: 28 }}><Text style={{ color: "#67e8f9", fontSize: 70 }}>The takeaway</Text><Text style={{ color: "white", fontSize: 110 }}>Simpler wins.</Text><Text style={{ color: "#94a3b8", fontSize: 42 }}>Keep the path people actually use.</Text></View>; }

# Content swap

<View style={{ width: 1696, height: 650 }}>
<Steps count={2}>{step => <ContentSwap active={step > 0} before={<Evidence />} after={<Takeaway />} style={{ width: 1696, height: 580 }} />}</Steps>
</View>

---
title: Spotlight and callouts
---

import { View, Text } from "react-native";
import { AttentionStage, AttentionTarget, Spotlight, Callout } from "slides:presenting/Attention";
import { useMotion } from "slides:presenting/Motion";

export function MovingIdea({ step }) {
  const position = useMotion(step === 1 ? [950, 300] : [150, 160], 1200);
  return <AttentionTarget id="idea" style={{ position: "absolute" }} frameStyle={() => { "worklet"; return { transform: [{ translateX: position.value[0] }, { translateY: position.value[1] }] }; }}><Text style={{ color: "white", fontSize: 90 }}>The idea</Text></AttentionTarget>;
}

# Spotlight and callouts

<View style={{ width: 1696, height: 650 }}>
<Steps count={3}>{step => <AttentionStage style={{ width: 1696, height: 580 }}><MovingIdea step={step} /><Spotlight target="idea" /><Callout target="idea">Follow the idea</Callout></AttentionStage>}</Steps>
</View>

---
title: Code walkthrough
---

import { View, Text } from "react-native";
import { CodeWalkthrough } from "slides:presenting/CodeWalkthrough";

export const code = `async function showResults(query) {
  const rows = await search(query);
  const visible = rows.slice(0, 20);
  setResults(visible);
  announce(visible.length);
}`;
export const highlights = [2, 3, 4];
export const notes = ["Fetch matching rows", "Keep the visible rows", "Publish the results"];

# Code walkthrough

<View style={{ width: 1696, height: 650 }}>
<Steps count={3}>{step => <CodeWalkthrough source={code} lines={[highlights[step], highlights[step]]} fontSize={34} explanation={<Text style={{ color: "white", fontSize: 52 }}>{notes[step]}</Text>} />}</Steps>
</View>

---
title: Freeze and annotate
---

import { View, Text } from "react-native";
import { FreezeFrame } from "slides:presenting/FreezeFrame";
import Animated, { useAnimatedStyle } from "react-native-reanimated";

export function Orbit({time}) { const style = useAnimatedStyle(() => ({transform: [{translateX: 600 + Math.sin(time.value) * 300},{translateY: 220 + Math.cos(time.value) * 100}]})); return <View style={{width: 1696,height: 650}}><Animated.View style={[{width: 100,height: 100,borderRadius: 50,backgroundColor: "#67e8f9"},style]} /></View>; }

# Freeze and annotate

<View style={{ width: 1696, height: 650 }}>
<Steps count={2}>{step => <FreezeFrame paused={step > 0} annotation={<Text style={{color: "white",fontSize: 48}}>Pause to explain this frame</Text>}>{time => <Orbit time={time} />}</FreezeFrame>}</Steps>
</View>
